NEW_FILES = {'tests/unit/test_worldskin_hardware.py': '"""A door\'s hardware keeps its own UVs on a kit module (0.242.0).\n\nZoo 1.127.0 paints a door\'s knob and plate (`<root>_LeafHardware`) the stoop\nrailing\'s black iron so that on a front the two are one material and one mesh.\nThey were not: the knob arrives in a `doorway_` kit module, which `_apply`\nworld-projects, and the railing in a `prop_`, which it leaves alone, and the\nEmpties\' per-side merge keys on `uv1_scale` and both triplanar flags -- cold\nrun 9392\'s `blocker_0` carried the iron twice on its street side (the\nfactory\'s `docs/cold_runs/cold_9392/meshes_blocker0_9392.out.txt`). A mesh\nnamed for one of `AUTHORED_UV_PARTS` is never projected, and the report\ncounts it.\n\nThese run the real script through a real Godot import over a generated\nmodule, as `test_worldskin_lit_faces.py` does. Skipped where no Godot is\ninstalled.\n"""\nfrom __future__ import annotations\n\nimport os\nimport re\nimport shutil\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parents[2]\nsys.path.insert(0, str(Path(__file__).resolve().parent))\n\nfrom glb_import_fixture import write_glb  # noqa: E402\nfrom tests.siblings import sibling_repo  # noqa: E402\n\nWORLDSKIN = ROOT / "assets" / "godot" / "zoo_worldskin.gd"\n\n_PROJECT = """\\\nconfig_version=5\n\n[application]\nconfig/name="worldskin hardware fixture"\n\n[rendering]\nrenderer/rendering_method="gl_compatibility"\n\n[importer_defaults]\n\nscene={\n"import_script/path": "res://zoo_worldskin.gd"\n}\n"""\n\n\ndef _godot() -> str | None:\n    for env in ("LF_GODOT", "DC_GODOT", "LOT_GODOT"):\n        p = os.environ.get(env)\n        if p and Path(p).is_file():\n            return p\n    usual = Path("C:/Godot/4.7/Godot_v4.7-stable_win64_console.exe")\n    if usual.is_file():\n        return str(usual)\n    return shutil.which("godot")\n\n\ngodot_required = pytest.mark.skipif(\n    _godot() is None, reason="no Godot binary; this test imports a real module")\n\nMODULE = "doorway_delco_1997_01_w100_mbrick_orange_enavy_o1d20e5.glb"\n\n\ndef _import(tmp_path: Path, meshes, materials) -> str:\n    proj = tmp_path / "pkg"\n    proj.mkdir()\n    (proj / "project.godot").write_text(_PROJECT, encoding="utf-8")\n    (proj / "zoo_worldskin.gd").write_text(WORLDSKIN.read_text(encoding="utf-8"), encoding="utf-8")\n    write_glb(proj / MODULE, meshes, materials, spread_uv=True)\n    out = subprocess.run([_godot(), "--headless", "--path", str(proj), "--import"],\n                         capture_output=True, text=True, timeout=300)\n    log = out.stdout + out.stderr\n    lines = [ln for ln in log.splitlines()\n             if ln.startswith(f"[worldskin] {MODULE}") and "world-projected" in ln]\n    # an unrecognised shape FAILS: a missing line means the pass did not run\n    assert len(lines) == 1, f"expected one report line, got {lines!r}\\n{log}"\n    return lines[0]\n\n\ndef _counts(line: str) -> tuple:\n    projected = int(re.search(r"(\\d+) material\\(s\\) world-projected", line).group(1))\n    m = re.search(r"(\\d+) hardware part\\(s\\) left on their own UVs", line)\n    assert m, f"no hardware count in the report: {line}"\n    return projected, int(m.group(1))\n\n\n@godot_required\ndef test_the_knob_keeps_its_uvs_and_the_leaf_is_still_projected(tmp_path):\n    """FAILS ON 0.241.0: both world-projected, and no hardware count."""\n    line = _import(tmp_path, [("Doorway_Leaf", 0), ("Doorway_LeafHardware", 1)],\n                   [("M_Skin_wood_panel_delco_1997", True), ("M_Skin_metal_painted_delco_1997_0f0f11", True)])\n    assert _counts(line) == (1, 1), line\n\n\n@godot_required\ndef test_a_doorway_with_no_hardware_is_projected_as_before(tmp_path):\n    """The control: a leaf alone is world-projected exactly as it was."""\n    line = _import(tmp_path, [("Doorway_Leaf", 0)], [("M_Skin_wood_panel_delco_1997", True)])\n    assert _counts(line) == (1, 0), line\n\n\ndef test_the_part_is_zoo_s_knob():\n    """One name, two readers: the node Zoo builds a door\'s hardware as is the\n    one this leaves on its UVs. Renamed on one side and not the other, the knob\n    is projected again and the front is two meshes of one iron."""\n    src = WORLDSKIN.read_text(encoding="utf-8")\n    assert \'const AUTHORED_UV_PARTS: Array = ["_LeafHardware"]\' in src\n    arch = "zoo_keeper/recipes/_arch.py"\n    zoo = sibling_repo("zoo", marker=arch)\n    if zoo is not None:\n        assert \'f"{root}_LeafHardware"\' in (zoo / arch).read_text(encoding="utf-8")\n'}
CHANGELOG = '## [0.242.0] - a door\'s hardware keeps its own UVs, so it merges with the stoop railing\n\n**Measured, cold run 9392** (the factory\'s `docs/cold_runs/cold_9392/`): Zoo 1.127.0 painted a door\'s knob the stoop\nrailing\'s black iron so that on a front the two would be one material and one mesh. The colour reached the package\n(`blocker_0`\'s knob mesh 0.8597 -> 0.2717 albedo), the merge did not: every Empty kept the same mesh count as 9391.\n`blocker_0`\'s street side carried two meshes of `M_Skin_metal_painted_delco_1997_0f0f11`, one with\n`uv1_scale (0.833, 0.833, 0.833) triplanar true`, one with `(0.833, 0.833, 1.0) triplanar false`, and\n`merge_empties.gd`\'s key reads both. The knob arrives inside a `doorway_` kit module, which `zoo_worldskin.gd`\'s\n`_apply` world-projects; the railing arrives in a `prop_`, which it leaves alone.\n\n### Changed\n- **`AUTHORED_UV_PARTS` (`["_LeafHardware"]`)**: a mesh whose node name ends with one is never world-projected, and\n  the import report counts it (`N hardware part(s) left on their own UVs`). A 6 cm knob shows no tile period to keep\n  continuous. On a front the knob now keys like the railing; a back door with no railing keeps its own mesh, as Zoo\n  1.127.0 said it would.\n\n### Tests\n- `tests/unit/test_worldskin_hardware.py` (fails on 0.241.0: the real import projects both materials of a doorway\n  with a knob and counts no hardware). Its third test pins the part\'s name against Zoo\'s `_arch.py`.\n\n'
OLD_VERSION, NEW_VERSION = '0.241.0', '0.242.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
